// GENERATED by scripts/sync-game-from-ios.sh from costquest-ios's
// CostQuest-Bridging-Header.h. A pod cannot have a bridging header, so the
// same declarations are the module's public header: Swift in this pod sees
// them through the pod's own module (-import-underlying-module).
#pragma once

// The whole surface the app links against: one header, one opaque handle.
//
// Engine/ is a verbatim copy of the mote project's src/. It is never edited
// here. Behaviour that has to differ on a phone is selected with a build flag,
// so the copy can be refreshed from upstream without a merge.
#import "mote_lib.h"

// Registers this app's handler for a tap on a game standing in the Unity
// world. Defined inside UnityFramework (Plugins/iOS/CQNativeBridge.m), not
// here: IL2CPP compiles its DllImport into a direct call, so the symbol has
// to exist when the FRAMEWORK links, which is too early for anything the app
// defines. See UnityBridge.
void CQSetAnchorTappedCallback(void (*callback)(const char *));

// As above, for a tap on one of the organiser's points during a game.
void CQSetCheckpointTappedCallback(void (*callback)(const char *));

// As above, for the moment the world is standing and can be shown.
void CQSetWorldReadyCallback(void (*callback)(int));

// As above, for the Duel scene: every event it reports, as a kind ("ready",
// "sfx", "finished", "quit") and a JSON payload. Defined in CQNativeBridge.m
// on the Unity side; only the device target references it (UnityDuelHost).
void CQSetDuelEventCallback(void (*callback)(const char *kind, const char *json));

// As above, for the Hub scene (the hero's hall on the home screen): "ready",
// "hero_tapped", "hero_long_pressed", "trophy_tapped" and a JSON payload.
// Only the device target references it (UnityHallHost).
void CQSetHubEventCallback(void (*callback)(const char *kind, const char *json));
